#include <cstdio>
#include <vector>

const int kMaxSquare = 64;

int roulette[4];

struct BoardState {
    int type;
    int value;
};

BoardState board[kMaxSquare];

int bp(int X, int Y) {
    std::vector<std::vector<double>> bp(Y + 1, std::vector<double>(1000, 0.0)); // Use a vector for dynamic size
    double prob = 1.0f / X;
    bp[0][0] = 1.0f;

    for (int n = 0; n < Y; n++) {
        for (int newValue = 0; newValue < 1000; newValue++) {
            if (bp[n][newValue] > 0) { // Only process non-zero probabilities
                for (int k = 0; k < X; k++) {
                    int pos = std::min(n + roulette[k], Y);

                    switch (board[pos].type) {
                        case 1:
                            bp[std::min(pos + board[pos].value, Y)][newValue] += bp[n][newValue] * prob;
                            break;
                        case 2:
                            bp[pos][newValue + board[pos].value] += bp[n][newValue] * prob;
                            break;
                        case 3:
                            bp[pos][std::max(newValue - board[pos].value, 0)] += bp[n][newValue] * prob;
                            break;
                        default:
                            bp[pos][newValue] += bp[n][newValue] * prob;
                            break;
                    }
                }
            }
        }
    }

    double res = 0.0f;
    for (int newValue = 0; newValue < 1000; newValue++)
        res += static_cast<double>(newValue) * bp[Y][newValue];
    return static_cast<int>(res);
}

int main() {
    while (true) {
        int X, Y, Z;
        scanf("%d %d %d", &X, &Y, &Z);
        if (X == 0) break;

        for (int i = 0; i < X; i++)
            scanf("%d", &roulette[i]);

        for (int i = 0; i < kMaxSquare; i++)
            board[i] = {0, 0};

        for (; Z > 0; Z--) {
            int N, E, A;
            scanf("%d %d %d", &N, &E, &A);
            board[N] = {E, A};
        }

        printf("%d\n", bp(X, Y));
    }
}

