    std::map<int, double> bp[kMaxSquare];
    double prob = 1.0f / X;
    bp[0][0] = 1.0f;

    for (int n = 0; n < Y; n++) {
        for (auto& it : bp[n]) {
            for (int k = 0; k < X; k++) {
                int pos = std::min(n + roulette[k], Y);
                switch (board[pos].type) {
                    case 1:
                        bp[std::min(pos + board[pos].value, Y)][it.first] += it.second * prob;
                        break;
                    case 2:
                        bp[pos][it.first + board[pos].value] += it.second * prob;
                        break;
                    case 3:
                        bp[pos][std::max(it.first - board[pos].value, 0)] += it.second * prob;
                        break;
                    default:
                        bp[pos][it.first] += it.second * prob;
                        break;
                }
            }
        }
    }

    double res = 0.0f;
    for (const auto& it : bp[Y])
        res += static_cast<double>(it.first) * it.second;
